const externalResources=[{id:'schema-koha-25-11',title:'Schéma de la base de données KOHA — 25.11',description:'Explorez les tables, les colonnes et les relations de la base de données KOHA pour repérer où sont stockées les informations et préparer les jointures de vos rapports SQL. Cette documentation technique concerne la version 25.11 : vérifiez sa correspondance avec la version installée dans le réseau avant d’utiliser une requête.',software:'KOHA',categories:['Documentation officielle'],keywords:['SQL','schéma','base de données','tables','colonnes','relations','jointures','rapports','administration','25.11'],externalUrl:'https://schema.koha-community.org/25_11/',edition:'KOHA 25.11',languageLabel:'Anglais'},{id:'code-rda-fr',title:'RDA-FR — Code de catalogage',description:'Consultez le code RDA-FR, transposition française du standard RDA pour le signalement des ressources des bibliothèques. Naviguez par entité, explorez les relations et retrouvez les référentiels et le glossaire pour approfondir les règles de description.',software:'Transversal',categories:['Documentation officielle'],keywords:['RDA-FR','catalogage','entités','relations','description','code'],externalUrl:'https://code.rdafr.fr/',edition:'Code de catalogage'},{id:'manuel-unimarc-bibliographique',title:'Manuel UNIMARC — format bibliographique',description:'Retrouvez la description du format bibliographique UNIMARC : blocs, zones, indicateurs et sous-zones. Cette référence, traduite par le Comité français UNIMARC, permet de vérifier la structure et l’emploi des zones lors du catalogage. Consultez les dates de mise à jour : certaines évolutions IFLA sont disponibles uniquement en anglais.',software:'Transversal',categories:['Documentation officielle'],keywords:['UNIMARC','manuel','catalogage','zones','champs','sous-zones','indicateurs','CfU','IFLA'],externalUrl:'https://www.transition-bibliographique.fr/unimarc/manuel-unimarc-format-bibliographique/#intro',edition:'Référence du format'},{id:'manuel-koha-officiel',title:'Manuel officiel de KOHA — en français',description:'Consultez la documentation de référence de la communauté KOHA pour comprendre les modules, retrouver une procédure et approfondir l’administration ou les préférences système. Ce lien pointe vers la dernière édition du manuel : certaines fonctions peuvent différer de la version installée et des paramètres du réseau.',software:'KOHA',categories:['Documentation officielle'],keywords:['manuel','documentation','catalogage','administration','préférences','officiel'],externalUrl:'https://koha-community.org/manual/latest/fr/html/index.html'}];
