async function api(path:string,options:RequestInit={}){const r=await fetch('/api/'+path,options);let d:any;try{d=await r.json();}catch{throw Error('Réponse du serveur non lisible.');}if(!r.ok)throw Error(d.error||'Opération impossible.');return d;}
function Icon({name,size=20}:{name:string;size?:number}){const C:any={home:Home,formation:GraduationCap,resources:Library,search:Search,admin:Settings,personal:UserRound,glossary:BookOpen,audit:ShieldCheck}[name]||FileText;return <C size={size} aria-hidden="true"/>;}
