 async function doSearch(e?:FormEvent){e?.preventDefault();setBusy(true);setResults(null);try{const d=await api('search?'+new URLSearchParams({q:search,software:filter,category}));setResults(d);setView('search');const u=new URL(location.href);u.search='?view=search';history.replaceState({},'',u);}catch(e:any){setError(e.message);}finally{setBusy(false);}}
